import os

def check_ini_files(root_dir, exclude_dir):
    results = []
    for root, dirs, files in os.walk(root_dir):
        # 'yedek' klasörünü atlamak için dirs'ten çıkarıyoruz (os.walk için)
        if os.path.basename(root) == "yedek":
            continue

        for file in files:
            if file.endswith(".ini"):
                full_path = os.path.join(root, file)
                # Eğer yolun içinde 'yedek' geçiyorsa atla (ekstra güvenlik)
                if os.path.normpath(exclude_dir) in os.path.normpath(full_path):
                    continue
                results.append(full_path)
    return results

