import os
import re

def verify_changes(root_dir, exclude_dir):
    target_files = []
    for root, dirs, files in os.walk(root_dir):
        if os.path.normpath(root).startswith(os.path.normpath(exclude_dir)):
            continue
        for f in files:
            if f.endswith(".ini"):
                target_files.append(os.path.join(root, f))

    report = []
    for file_path in target_files:
        try:
            with open(file_path, 'rb') as f:
                content = f.read()

            # UTF-8 BOM kontrolü
            has_bom = content.startswith(b'\xef\xbb\xbf')
            text = content.decode('utf-8-sig')

            # [veritabani] bölümündeki port değerini kontrol et
            pattern_section = re.compile(r'\[\s*veritabani\s*\][\s\S]*?(?=\n\s*\[|\Z)', re.IGNORECASE)
            section_match = pattern_section.search(text)

            port_val = "Bulunamadı"
            if section_match:
                section_text = section_match.group(0)
                # Regex: port = 5432 (boşluklar dahil)
                port_match = re.search(r'^(\s*port\s*=\s*)(5432)(\s*)$', section_text, re.IGNORECASE | re.MULTILINE)
                if port_match:
                    port_val = f"5432 (Hatalı! Değişmeliydi)"
                else:
                    # 6543 olup olmadığını kontrol et
                    port_match_new = re.search(r'^(\s*port\s*=\s*)(6543)(\s*)$', section_text, re.IGNORECASE | re.MULTILINE)
                    if port_match_new:
                        port_val = "6543 (Doğru)"
                    else:
                        port_val = "Başka bir değer veya format"
            else:
                port_val = "Bölüm bulunamadı"

            report.append({
                'file': file_path,
                'has_bom': has_bom,
                'port_status': port_val
            })
        except Exception as e:
            report.append({'file': file_path, 'error': str(e)})

    return report

root = "servisler"
exclude = os.path.join(root, "yedek")
results = verify_changes(root, exclude)
for r in results:
    print(r)

